       function createSidebar() {
         const aside = document.createElement('aside');
         aside.className = 'sidebar-card';
         aside.setAttribute('aria-labelledby', 'tips-title');
         aside.innerHTML = `
           <h2 id="tips-title">Before you delete</h2>
           <p>This confirmation keeps destructive actions intentional and easy to cancel.</p>
         `;

         const list = document.createElement('ul');
         list.className = 'notes';
         list.innerHTML = `
