           <li>Cancel is the default focus when the dialog opens.</li>
           <li>Escape closes the dialog without deleting anything.</li>
         `;
         aside.append(list);

         return aside;
       }

       function createDeleteDialog() {
         const dialog = document.createElement('dialog');
         dialog.id = 'confirm-delete-dialog';
         dialog.setAttribute('aria-labelledby', 'confirm-delete-title');
         dialog.setAttribute('aria-describedby', 'confirm-delete-body');

         dialog.innerHTML = `
           <div class="dialog-panel">
             <p class="dialog-kicker">Confirm deletion</p>
             <h2 id="confirm-delete-title">Delete this image from your library?</h2>
             <p id="confirm-delete-body" class="dialog-body">
               This action will remove the image from your library. You can't undo it after confirming.
             </p>
             <div class="dialog-actions">
               <button type="button" class="secondary" data-close-delete-dialog autofocus>Cancel</button>
               <button type="button" class="danger" data-confirm-delete>Delete</button>
             </div>
           </div>
         `;

         return dialog;
       }

       function App() {
         const main = document.createElement('main');
         main.id = 'main';
         main.className = 'shell';
         main.setAttribute('tabindex', '-1');

         const header = document.createElement('header');
         header.className = 'topbar';
         header.innerHTML = `
           <div class="brand">
             <p class="eyebrow">Library preview</p>
             <h1>Image Preview</h1>
             <p>Review the photo, then confirm whether it should stay in your library.</p>
