       const app = document.getElementById('app');
       const dialog = createDeleteDialog();
       app.replaceChildren(App(), dialog);

       const trigger = document.querySelector('[data-open-delete-dialog]');
       const closeButton = dialog.querySelector('[data-close-delete-dialog]');
       const confirmButton = dialog.querySelector('[data-confirm-delete]');
       const status = document.getElementById('status');

       function openDialog() {
         dialog.showModal();
       }

       function closeDialog() {
         dialog.close();
       }

       trigger.addEventListener('click', openDialog);
       closeButton.addEventListener('click', closeDialog);
       confirmButton.addEventListener('click', () => {
         status.textContent = 'Image deleted from your library.';
         closeDialog();
